#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$env:NODE_PATH="$basedir/..;$basedir/../../../node_modules"
$exe=""
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  $exe=".exe"
}
$ret=0
if (Test-Path "$basedir/node$exe") {
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe" "$basedir/../../../rollup-plugin-visualizer@7.1.1_rolldown@1.2.4_rollup@4.62.4/node_modules/rollup-plugin-visualizer/dist/bin/cli.js" $args
  } else {
    & "$basedir/node$exe" "$basedir/../../../rollup-plugin-visualizer@7.1.1_rolldown@1.2.4_rollup@4.62.4/node_modules/rollup-plugin-visualizer/dist/bin/cli.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe" "$basedir/../../../rollup-plugin-visualizer@7.1.1_rolldown@1.2.4_rollup@4.62.4/node_modules/rollup-plugin-visualizer/dist/bin/cli.js" $args
  } else {
    & "node$exe" "$basedir/../../../rollup-plugin-visualizer@7.1.1_rolldown@1.2.4_rollup@4.62.4/node_modules/rollup-plugin-visualizer/dist/bin/cli.js" $args
  }
  $ret=$LASTEXITCODE
}
exit $ret
